export const handler = async (input) => {
  // dpv-score-v2 (batch 3 C4): optional dimensions without evidence are left out of the denominator and
  // the score is normalized to 100 over the scored weight. The three core fit dimensions (product,
  // market, buyer type) always stay in the denominator: a company with no product evidence must not
  // look like a perfect fit. A tier above C also needs >= 60 evidence coverage.
  // Company size: medium highest, very large down-weighted (better fit for small exporters).
  const facts = input.facts || {};
  const core = new Set(['product_fit', 'market_fit', 'importer_wholesaler_fit']);
  const specs = {
    product_fit: { max: 20, values: { VERIFIED: 20, TARGET: 20, SUPPORTED: 12, RELATED: 6 } },
    market_fit: { max: 15, values: { TARGET: 15, VERIFIED: 15, SUPPORTED: 10, ADJACENT: 8 } },
    importer_wholesaler_fit: { max: 15, values: { VERIFIED: 15, SUPPORTED: 10, RETAIL_CHAIN: 12, BUSINESS_TRADING: 5 } },
    chain_supply_evidence: { max: 15, values: { VERIFIED: 15, SUPPORTED: 10, LIMITED: 5 } },
    distribution_scale: { max: 10, values: { MEDIUM: 10, SMALL: 8, LARGE: 6, MICRO: 4, ENTERPRISE: 3, STRONG: 6, LIMITED: 4 } },
    recent_buying_signal: { max: 10, values: { VERIFIED_RECENT: 10, SUPPORTED_RECENT: 5 } },
    decision_maker_quality: { max: 10, values: { VERIFIED: 10, SUPPORTED: 5 } },
    contact_validity: { max: 5, values: { MAILBOX_VERIFIED: 5, DOMAIN_MX_VERIFIED: 4, ACCEPT_ALL_HIGH: 4, PUBLICLY_OBSERVED: 3, FORM_OR_PHONE: 2, WEBSITE_ONLY: 1 } }
  };
  const dimension_scores = {};
  const reason_codes = [];
  const fired_rules = [];
  const evidenceIds = [];
  let raw = 0;
  let coveredWeight = 0;
  let scoredWeight = 0;
  for (const [key, spec] of Object.entries(specs)) {
    const fact = facts[key] || {};
    const ids = Array.isArray(fact.evidence_ids) ? fact.evidence_ids.filter(Boolean) : [];
    const hasEvidence = ids.length > 0 && Number(fact.confidence || 0) > 0;
    let points = null;
    let reason = key.toUpperCase() + '_UNKNOWN';
    if (hasEvidence && key === 'recent_buying_signal' && spec.values[String(fact.value || '').toUpperCase()] && !fact.observed_at) {
      reason = 'RECENT_SIGNAL_DATE_MISSING';
    } else if (hasEvidence) {
      coveredWeight += spec.max;
      scoredWeight += spec.max;
      points = spec.values[String(fact.value || '').toUpperCase()] || 0;
      reason = points > 0 ? key.toUpperCase() + '_' + String(fact.value).toUpperCase() : key.toUpperCase() + '_NO_MATCH';
      evidenceIds.push(...ids);
      raw += points;
    } else if (core.has(key)) {
      scoredWeight += spec.max;
      points = 0;
      reason = key.toUpperCase() + '_EVIDENCE_MISSING';
    } else if (key === 'decision_maker_quality') {
      reason = 'DECISION_MAKER_NOT_YET_ENRICHED';
    } else {
      reason = key.toUpperCase() + '_EVIDENCE_MISSING';
    }
    dimension_scores[key] = { points: points === null ? 0 : points, maximum: spec.max, included: points !== null, reason_codes: [reason], evidence_ids: ids };
    reason_codes.push(reason);
    if (points > 0) fired_rules.push(key + ':' + String(fact.value).toUpperCase());
  }
  const total = scoredWeight > 0 ? Math.max(0, Math.min(100, Math.round(raw * 100 / scoredWeight))) : 0;
  const evidence_coverage = Math.round(coveredWeight * 100) / 100;
  let tier = total >= 75 ? 'A' : total >= 55 ? 'B' : 'C';
  if (tier !== 'C' && evidence_coverage < 60) { tier = 'C'; reason_codes.push('SCORE_COVERAGE_TOO_LOW_FOR_TIER'); }
  if (tier === 'A' && !(dimension_scores.product_fit.points > 0)) { tier = 'B'; reason_codes.push('PRODUCT_EVIDENCE_REQUIRED_FOR_TIER_A'); }
  return {
    final_score: total,
    raw_points: raw,
    scored_weight: scoredWeight,
    tier,
    evidence_coverage,
    dimension_scores,
    reason_codes: [...new Set(reason_codes)],
    fired_rules,
    evidence_ids: [...new Set(evidenceIds)],
    rule_version: 'dpv-score-v2'
  };
};
